mapper.update:
UPDATE dm_auth_mfa_challenge
SET
    retry_count = retry_count + 1,
    gmt_modified = now()
WHERE
    id = #{id}
    AND challenge_token_hash = #{challengeTokenHash}
    AND action_type = #{actionType}
    AND expire_time_ms  >=  #{nowMs}
    AND retry_count  <  #{maxRetryCount}

mapper.delete:
